  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>—</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>—</p>
      </div>
    </div>
  )
}

export function RevenueChartSkeleton() {
  return (
    <div className="chart">
      <h2>Revenue</h2>
      <p>Loading revenue...</p>
    </div>
  )
}

export function LatestInvoicesSkeleton() {
  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <p>Loading invoices...</p>
    </div>
  )
}

import {
  CardStatsSkeleton,
  RevenueChartSkeleton,
  LatestInvoicesSkeleton,
} from './skeletons'

export default function Loading() {
  return (
    <main>
      <h1>Dashboard</h1>
      <CardStatsSkeleton />
      <RevenueChartSkeleton />
      <LatestInvoicesSkeleton />
    </main>
  )
}

import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import { getDashboardData } from './data'
import {
  CardStatsSkeleton,
  RevenueChartSkeleton,
  LatestInvoicesSkeleton,
} from './skeletons'

async function CardStatsLoader() {
  const data = await getDashboardData()
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartLoader() {
  const data = await getDashboardData()
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesLoader() {
  const data = await getDashboardData()
  return <LatestInvoices invoices={data.invoices} />
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsLoader />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChartLoader />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoicesLoader />
      </Suspense>
    </main>
  )
}

